private static void deleteRecursive(File f) throws IOException {
    if (!f.exists()) {
        return;
    }
    if (f.isDirectory()) {
        File[] contents = f.listFiles();
        if (contents != null) {
            for (File child : contents) {
                deleteRecursive(child);
            }
        }
    }
