    }
    List<ThreadSnapshot> result = new ArrayList<>();
    boolean filter = timeRanges != null && !timeRanges.isEmpty();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            ThreadSnapshot snapshot;
            try {
                // Assuming ThreadSnapshot has a static parser from a single line string
                snapshot = ThreadSnapshot.parseFromString(line);
            } catch (Exception e) {
                // Skip malformed lines
                continue;
            }
            if (!filter) {
                result.add(snapshot);
                continue;
