            }
            // Try to extract a timestamp from the line
            Matcher m = tsPattern.matcher(line);
            if (!m.find()) {
                // no numeric part – skip this line
                continue;
            }
            long ts;
            try {
                ts = Long.parseLong(m.group(1));
            } catch (NumberFormatException e) {
                // malformed number – skip line
                continue;
            }
            // Determine if this timestamp falls into any supplied range
            boolean inAnyRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                // Assume the range object has a method 'contains(long)' that checks the range
                boolean inRange;
                try {
                    inRange = range.contains(ts);
                } catch (NoSuchMethodError | IllegalAccessError | Throwable t) {
                    // If the method is not available or fails, skip this range
                    inRange = false;
                }
                if (inRange) {
                    inAnyRange = true;
                    break;
